(function(E){ const x = E["sales-m3"] = E["sales-m3"] || {units:{}}; x.units["sales-3-3"] = {"grammar":{"id":"c-sales-3-3-g","level":"B1","course":"sales","unit":"sales-3-3","title":"Order confirmations: is packed, will be shipped","titleTr":"Sipariş onayları: is packed, will be shipped","titleFa":"تأیید سفارش: is packed و will be shipped","formsTable":{"headers":{"en":["Time","Passive","Example"],"tr":["Zaman","Edilgen","Örnek"],"fa":["زمان","مجهول","مثال"]},"rows":[["always / usually","am / is / are + past participle","All cartons are packed on pallets."],["future","will be + past participle","The first delivery will be shipped on 1 May."],["done now","has / have been + past participle","Your order has been confirmed."]]},"wrong":"The first delivery will shipped on 1 May.","right":"The first delivery will be shipped on 1 May.","blank":{"sentence":"All cartons ___ on pallets.","word":"are packed","distractors":["are pack","are packing"]},"wrong2":"Your order has confirmed.","right2":"Your order has been confirmed.","blank2":{"sentence":"The documents will ___ by courier on Friday.","word":"be sent","distractors":["sent","send"]},"expParts":{"tryFrom":"blank","rule":[{"en":"The goods matter, not who packs them: use be + past participle.","tr":"Önemli olan mal, onu kimin paketlediği değil: be + fiilin üçüncü hâli kullan.","fa":"چیزی که مهم است کالاست، نه کسی که بسته‌بندی‌اش می‌کند؛ پس be و اسم مفعول بیاور.","ex":"All cartons are packed on pallets."},{"en":"For a future step, use will be + past participle.","tr":"Gelecekteki bir adım için will be + fiilin üçüncü hâli kullan.","fa":"برای مرحله‌ای در آینده will be و اسم مفعول بیاور.","ex":"The first delivery will be shipped on 1 May."},{"en":"For a step just done, use has / have been + past participle.","tr":"Az önce tamamlanan bir adım için has / have been + fiilin üçüncü hâli kullan.","fa":"برای مرحله‌ای که همین حالا انجام شده has been یا have been و اسم مفعول بیاور.","ex":"Your order has been confirmed."},{"en":"Use a real date or clear event, so the buyer can plan.","tr":"Gerçek bir tarih ya da açık bir olay kullan ki alıcı plan yapabilsin.","fa":"تاریخ واقعی یا یک رویداد روشن بگو تا خریدار بتواند برنامه‌ریزی کند.","ex":"six weeks after the deposit arrives"}],"test":{"en":"Can the goods do the action themselves? If not, check there is a be and a past participle.","tr":"Mal bu eylemi kendisi yapabilir mi? Yapamıyorsa bir be ve fiilin üçüncü hâli olup olmadığına bak.","fa":"آیا کالا خودش می‌تواند این کار را بکند؟ اگر نه، ببین be و اسم مفعول در جمله هست یا نه."},"contrast":{"en":"Turkish makes the passive with a verb ending ('paketlenir', 'gönderilecek'), with no separate 'be', so learners write 'will shipped'. Persian adds «شدن» («ارسال خواهد شد»), which works like English be.","tr":"Türkçede edilgen yapı fiil ekiyle kurulur ('paketlenir', 'gönderilecek'); ayrı bir 'be' yoktur. Bu yüzden İngilizcede 'will shipped' yazılıyor. İngilizcede be şarttır: will be shipped.","fa":"در فارسی مجهول را با «شدن» می‌سازیم: «ارسال خواهد شد»، «بسته‌بندی می‌شوند». فعل be در انگلیسی همان نقش «شدن» را دارد؛ پس نباید جا بیفتد: will be shipped."}},"errorWatch":[{"find":["will shipped","will sent","will delivered","will packed","will be ship","will be send","will be deliver","will be pack","are pack","is pack"],"fix":{"en":"Passive = be + past participle: 'will be shipped', 'are packed'.","tr":"Edilgen = be + fiilin üçüncü hâli: 'will be shipped', 'are packed'.","fa":"مجهول یعنی be و اسم مفعول: will be shipped و are packed."}},{"find":["order has confirmed","deposit has received","order was confirm","deposit was receive"],"fix":{"en":"The order doesn't confirm anything: 'Your order has been confirmed.'","tr":"Sipariş bir şeyi onaylamaz: 'Your order has been confirmed.'","fa":"سفارش چیزی را تأیید نمی‌کند: «Your order has been confirmed.»"}}]},"b2":{"id":"c-sales-3-3-b2","level":"B2","track":"B2","course":"sales","unit":"sales-3-3","title":"Rules in a contract: must be paid, can't be shipped","titleTr":"Sözleşmedeki kurallar: must be paid, can't be shipped","titleFa":"قاعده‌های قرارداد: must be paid و can't be shipped","formsTable":{"headers":{"en":["Modal","be + past participle","Example"],"tr":["Modal","be + fiilin üçüncü hâli","Örnek"],"fa":["فعل وجهی","be و اسم مفعول","مثال"]},"rows":[["must","be paid","The deposit must be paid first."],["can't","be shipped","The goods can't be shipped without the certificate."],["should","be signed","It should be signed by both sides."]]},"wrong":"The deposit must paid before production starts.","right":"The deposit must be paid before production starts.","blank":{"sentence":"Any change to the labels ___ agreed in writing.","word":"must be","distractors":["must","must to be"]},"wrong2":"The goods can't be ship without the certificate.","right2":"The goods can't be shipped without the certificate.","blank2":{"sentence":"The order confirmation should ___ by both sides.","word":"be signed","distractors":["signed","be sign"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"Modal + be + past participle: a rule with no person.","tr":"Modal + be + fiilin üçüncü hâli: kişisiz bir kural.","fa":"با فعل وجهی، be و اسم مفعول قاعده‌ای می‌گویی که نام کسی در آن نیست.","ex":"The deposit must be paid first."},{"en":"must = required; can't = not allowed; should = expected.","tr":"must = zorunlu; can't = izin yok; should = beklenen.","fa":"کلمه‌ی must یعنی الزامی، can't یعنی مجاز نیست و should یعنی انتظار می‌رود.","ex":"The goods can't be shipped without the certificate."},{"en":"Keep all three parts; never drop be or -ed.","tr":"Üç parçayı da koru; be'yi ya da -ed'i asla atlama.","fa":"هر سه بخش را نگه دار و be یا اسم مفعول را جا نینداز.","ex":"It should be signed by both sides."}],"test":{"en":"Count three parts after the subject: a modal, be, and a past participle.","tr":"Özneden sonra üç parça say: bir modal, be ve fiilin üçüncü hâli.","fa":"بعد از فاعل سه بخش بشمار: یک فعل وجهی، be و یک اسم مفعول."},"contrast":{"en":"Turkish says 'ödenmelidir' and Persian «باید پرداخت شود»: one word or phrase carries it all. English needs three separate parts: must be paid.","tr":"Türkçede 'ödenmelidir' deriz; tek kelime her şeyi taşır. İngilizcede üç ayrı parça gerekir: must be paid.","fa":"در فارسی می‌گوییم «باید پرداخت شود». در انگلیسی سه بخش جدا لازم است: must be paid. «پرداخت شود» همان be paid است."}},"errorWatch":[{"find":["must paid","should signed","can shipped","can't shipped","must agreed","must be pay","can't be ship","should be sign","must be agree"],"fix":{"en":"Modal + be + past participle: 'must be paid', 'can't be shipped'.","tr":"Modal + be + fiilin üçüncü hâli: 'must be paid', 'can't be shipped'.","fa":"فعل وجهی، be و اسم مفعول را با هم بیاور: must be paid و can't be shipped."}}],"useIn":{"en":"B2: write one rule in your confirmation with must be, can't be or should be + past participle.","tr":"B2: onayına must be, can't be ya da should be + fiilin üçüncü hâli ile bir kural yaz.","fa":"مسیر B2: در تأییدیه‌ات یک قاعده با must be، can't be یا should be و اسم مفعول بنویس."},"exitItem":{"from":"sales-3-3","kind":"blank","prompt":"Claims for damage ___ within seven days of delivery.","options":["must make","must be make","must be made"],"correct":2,"why":{"en":"must be made: claims receive the action, so must + be + past participle. 'Must make' is active, and 'must be make' drops the participle.","tr":"must be made: talepler eylemi alır, bu yüzden must + be + üçüncü hâl. 'Must make' etkendir; 'must be make' üçüncü hâli düşürür.","fa":"must be made درست است، چون ادعا ثبت می‌شود و ساختار must و be و اسم مفعول لازم است. must make معلوم است و must be make اسم مفعول ندارد."}}},"vocab":{"id":"c-sales-3-3-v","level":"B1","category":"vocab","course":"sales","unit":"sales-3-3","goals":["career"],"title":{"en":"Orders and documents","tr":"Siparişler ve belgeler","fa":"سفارش و مدارک"},"cards":[{"word":"order confirmation","sentence":"We sent the order confirmation within an hour.","meaning":{"en":"A document that repeats exactly what was ordered and agreed.","tr":"sipariş onayı.","fa":"تأییدیه‌ی سفارش"}},{"word":"purchase order","sentence":"Their purchase order arrived this morning.","meaning":{"en":"The buyer's official document that orders goods.","tr":"satın alma siparişi.","fa":"سفارش خرید"}},{"word":"packing list","sentence":"The packing list shows the weight of each box.","meaning":{"en":"A list of what is in each package.","tr":"çeki listesi","fa":"پکینگ لیست (فهرست بسته‌بندی)"}},{"word":"specification","sentence":"Please check the specification before we start.","meaning":{"en":"Exact details of what a product must be.","tr":"teknik özellikler, şartname.","fa":"مشخصات فنی"}},{"word":"shipment","sentence":"The shipment left the port on Tuesday.","meaning":{"en":"Goods sent together at one time.","tr":"sevkiyat.","fa":"محموله"}},{"word":"schedule","sentence":"Here is the delivery schedule for the year.","meaning":{"en":"A plan with times and dates.","tr":"takvim, program.","fa":"برنامه‌ی زمانی"}},{"word":"confirm","sentence":"Could you confirm the delivery address?","meaning":{"en":"To say that something is true or agreed.","tr":"onaylamak, teyit etmek.","fa":"تأیید کردن"}},{"word":"in writing","sentence":"Please send any changes in writing.","meaning":{"en":"Written down, not only said.","tr":"yazılı olarak.","fa":"کتبی"}},{"word":"quantity","sentence":"The quantity on the invoice is wrong.","meaning":{"en":"How many.","tr":"miktar.","fa":"مقدار؛ تعداد"}},{"word":"certificate of origin","sentence":"Customs asked for a certificate of origin.","meaning":{"en":"A paper that says where goods were made.","tr":"menşe belgesi","fa":"گواهی مبدأ"}}]},"judge":{"id":"c-sales-3-3-j","course":"sales","unit":"sales-3-3","type":"judge","title":{"en":"Would you send this confirmation?","tr":"Bu onayı gönderir miydin?","fa":"این تأییدیه را می‌فرستی؟"},"prompt":"Four confirmations for an order of 500 kilos of dried apricots.","parts":["Order number","All terms","Real date"],"instruction":{"en":"Tap what each confirmation has. The one to send has all three.","tr":"Her onayda ne olduğuna dokun. Gönderilecek olanda üçü de var.","fa":"روی چیزهایی که هر تأییدیه دارد بزن. تأییدیه‌ای که باید بفرستی هر سه را دارد."},"items":[{"by":"New rep","answer":"Thank you for your order. It is all fine, and we'll ship it soon.","present":[],"fix":{"en":"Which order? What terms? When? A confirmation with no facts protects nobody.","tr":"Hangi sipariş? Hangi koşullar? Ne zaman? Bilgi içermeyen bir onay kimseyi korumaz.","fa":"کدام سفارش؟ چه شرایطی؟ کی؟ تأییدیه‌ی بدون واقعیت از کسی محافظت نمی‌کند."}},{"by":"Sales rep","answer":"Your order 2208 has been confirmed and will be shipped on 12 June.","present":["Order number","Real date"],"fix":{"en":"Clear, but the terms are missing. Repeat the quantity, price, Incoterm and payment.","tr":"Net ama koşullar eksik. Miktarı, fiyatı, Incoterm'i ve ödemeyi tekrar et.","fa":"روشن است، ولی شرایط جا افتاده است. مقدار، قیمت، اینکوترم و پرداخت را تکرار کن."}},{"by":"AI tool","answer":"We hereby acknowledge receipt of your esteemed order: 500 kg at USD 6.20, FOB Mersin, Incoterms 2020, 30% in advance and the balance against documents.","present":["All terms"],"fix":{"en":"The terms are all there, but the style is stiff, and there's no order number or date.","tr":"Koşulların hepsi var ama üslup katı ve sipariş numarası ya da tarih yok.","fa":"همه‌ی شرایط هست، ولی لحن خشک است و شماره‌ی سفارش و تاریخ ندارد."}},{"by":"Good model","answer":"Your order 2208 has been confirmed: 500 kg at USD 6.20, FOB Mersin, Incoterms 2020, 30% in advance and the balance against documents. It will be shipped on 12 June.","present":["Order number","All terms","Real date"],"fix":null}]},"speaking":{"id":"sales-3-3","course":"sales","unit":"sales-3-3","topic":{"en":"Reading back the order","tr":"Siparişi okuyarak doğrulamak","fa":"بازخوانی سفارش"},"warmup":{"en":"Which document has caused you trouble, or sounds hardest to you?","tr":"Hangi belge başını ağrıttı ya da sana en zor görünüyor?","fa":"کدام مدرک برایت دردسر شده یا سخت‌تر به نظر می‌رسد؟"},"questions":[{"en":"Read the order back to the buyer by phone: quantity, price, Incoterm, payment, date. Yours, or: 500 kg at USD 6.20, FOB Mersin, 30% in advance, ships on 12 June.","tr":"Siparişi telefonda alıcıya okuyarak doğrula: miktar, fiyat, Incoterm, ödeme, tarih. Kendi siparişin ya da şu: 500 kg, kilosu 6,20 dolar, FOB Mersin, %30 peşin, 12 Haziran'da yükleme.","fa":"سفارش را پشت تلفن برای خریدار بخوان: مقدار، قیمت، اینکوترم، پرداخت، تاریخ. سفارش خودت یا این: ۵۰۰ کیلو، کیلویی ۶٫۲۰ دلار، FOB مرسین، ۳۰ درصد پیش‌پرداخت، ارسال ۱۲ ژوئن."},{"en":"The buyer's PO says 30 days to pay, but your quote said 30% in advance. Raise it politely.","tr":"Alıcının siparişinde 30 gün vade yazıyor ama teklifinde %30 peşin yazıyordu. Kibarca belirt.","fa":"در سفارش خریدار ۳۰ روز مهلت نوشته شده، ولی پیشنهاد تو ۳۰ درصد پیش‌پرداخت بوده. مؤدبانه مطرحش کن."},{"en":"Explain which documents will be sent, and when, using the passive.","tr":"Hangi belgelerin ne zaman gönderileceğini edilgen yapıyla açıkla.","fa":"با فعل مجهول توضیح بده چه مدارکی کی فرستاده می‌شوند."}],"followups":[{"en":"Which documents does your product need for your main market? Who can tell you?","tr":"Ürünün ana pazarın için hangi belgeleri gerektiriyor? Bunu sana kim söyleyebilir?","fa":"محصولت برای بازار اصلی‌ات چه مدارکی لازم دارد؟ چه کسی می‌تواند به تو بگوید؟"}],"expressions":[{"phrase":"Let me read that back to you.","meaning":{"en":"Checks the order aloud.","tr":"Siparişi sesli kontrol eder.","fa":"سفارش را با صدای بلند بررسی می‌کند."}},{"phrase":"I noticed a difference between ... and ...","meaning":{"en":"Raises a mismatch politely.","tr":"Bir uyumsuzluğu kibarca belirtir.","fa":"مؤدبانه یک مغایرت را مطرح می‌کند."}},{"phrase":"... will be sent by ...","meaning":{"en":"Says when the documents go.","tr":"Belgelerin ne zaman gideceğini söyler.","fa":"می‌گوید مدارک کی فرستاده می‌شوند."}}],"model":"Let me read that back to you. Five hundred kilos at six dollars twenty, FOB Mersin, Incoterms 2020. I noticed a difference between your order and our quote. Your order says thirty days to pay, but we quoted thirty percent in advance. Could you confirm which is right? The goods will be shipped on twelve June, and the documents will be sent by courier.","selfCheck":[{"en":"I read back every term.","tr":"Her koşulu okuyarak doğruladım.","fa":"همه‌ی شرایط را بازخوانی کردم."},{"en":"I raised the difference calmly.","tr":"Farkı sakince belirttim.","fa":"اختلاف را آرام مطرح کردم."},{"en":"I used be + past participle.","tr":"Be + fiilin üçüncü hâlini kullandım.","fa":"be و اسم مفعول به کار بردم."},{"en":"I said real dates.","tr":"Gerçek tarihler söyledim.","fa":"تاریخ‌های واقعی گفتم."}]},"writing":{"id":"c-sales-3-3-w","course":"sales","unit":"sales-3-3","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your order confirmation","tr":"Sipariş onayın","fa":"تأییدیه‌ی سفارش تو"},"portfolio":"sales-final-5","prompt":{"en":"Write an order confirmation (80-110 words) for your own order, or: order 2208; 500 kg dried apricots; USD 6.20 a kilo; FOB Mersin; 30% in advance, the balance against documents; ships 12 June. Confirm every term in the passive, list the documents you will send (commercial invoice, packing list, bill of lading, certificate of origin), and ask for one check.","tr":"Kendi siparişin ya da şunun için sipariş onayı yaz (80-110 kelime): sipariş 2208; 500 kg kuru kayısı; kilosu 6,20 dolar; FOB Mersin; %30 peşin, kalanı belge karşılığı; 12 Haziran'da yüklenecek. Her koşulu edilgen yapıyla onayla, göndereceğin belgeleri yaz (ticari fatura, çeki listesi, konşimento, menşe belgesi) ve bir kontrol iste.","fa":"برای سفارش خودت، یا این سفارش، تأییدیه بنویس (۸۰ تا ۱۱۰ کلمه): سفارش ۲۲۰۸؛ ۵۰۰ کیلو زردآلوی خشک؛ کیلویی ۶٫۲۰ دلار؛ FOB مرسین؛ ۳۰ درصد پیش‌پرداخت، مانده در برابر مدارک؛ ارسال ۱۲ ژوئن. همه‌ی شرایط را با فعل مجهول تأیید کن، مدارکی را که می‌فرستی بنویس (فاکتور تجاری، پکینگ لیست، بارنامه، گواهی مبدأ) و از خریدار بخواه آن‌ها را بررسی کند."},"model":"Dear Mr Petrov,\n\nYour order 2208 has been confirmed: 500 kg of dried apricots at USD 6.20 a kilo, FOB Mersin, Incoterms 2020. Payment is 30% in advance, and the balance is paid against documents. The goods will be shipped on 12 June, as soon as the deposit has been received.\n\nThe commercial invoice, packing list, bill of lading and certificate of origin will be sent by courier after loading. Could you check the delivery name and address, and confirm them in writing?\n\nBest regards","frame":"Dear ___,\n\nYour order ___ has been confirmed: ___, ___, Incoterms 2020. Payment is ___. The goods will be shipped on ___.\n\nThe ___ will be sent by ___. Could you check ___ and confirm in writing?\n\nBest regards","words":[{"word":"has been confirmed"},{"word":"will be shipped"},{"word":"packing list"}],"minWords":70,"minSentences":4,"rubric":["Task done: order number, all terms, shipping date, documents, one check","Organised: terms first, documents second, the request last","Language: passive with be + past participle","Tone: clear and exact; nothing left to guess"],"rubricI18n":{"tr":["Görev: sipariş numarası, tüm koşullar, yükleme tarihi, belgeler, bir kontrol","Düzen: önce koşullar, sonra belgeler, en sonda istek","Dil: be + fiilin üçüncü hâliyle edilgen yapı","Üslup: açık ve net; tahmine bir şey bırakmıyor"],"fa":["کامل بودن کار: شماره‌ی سفارش، همه‌ی شرایط، تاریخ ارسال، مدارک، درخواست بررسی","نظم: اول شرایط، بعد مدارک، آخر درخواست","زبان: مجهول با be و اسم مفعول","لحن: روشن و دقیق؛ چیزی برای حدس زدن نمانده"]}},"exit":{"id":"c-sales-3-3-x","course":"sales","unit":"sales-3-3","type":"exit","items":[{"from":"sales-3-3","kind":"blank","prompt":"The container ___ on Friday, so the bill of lading will follow.","options":["will loaded","will be loaded","will be load"],"correct":1,"point":2,"why":{"en":"will be loaded: the container receives the action, so use will be + past participle. 'Will loaded' drops be; 'will be load' drops -ed.","tr":"will be loaded: konteyner eylemi alır, bu yüzden will be + üçüncü hâl. 'Will loaded' be'yi düşürür; 'will be load' -ed'i düşürür.","fa":"will be loaded درست است، چون کانتینر بار زده می‌شود و ساختار will be و اسم مفعول لازم است. will loaded بدون be و will be load بدون ‎-ed غلط‌اند."}},{"from":"sales-3-3","kind":"mcq","prompt":"Which document lists what is in each box?","options":["Packing list","Certificate of origin","Proforma invoice"],"correct":0,"point":1,"why":{"en":"Packing list: it shows what is in each box. A certificate of origin says where the goods were made; a proforma is a draft invoice.","tr":"Packing list: her kutuda ne olduğunu gösterir. Menşe belgesi malın nerede üretildiğini söyler; proforma ön faturadır.","fa":"Packing list محتوای هر جعبه را نشان می‌دهد. گواهی مبدأ می‌گوید کالا کجا ساخته شده و پروفرما پیش‌فاکتور است."}},{"from":"sales-3-3","kind":"mcq","prompt":"With a letter of credit, what do the banks check?","options":["The goods in the container","The documents","The factory"],"correct":1,"point":3,"why":{"en":"The documents: under a letter of credit, banks pay against papers that match the terms. They don't inspect the goods or the factory.","tr":"The documents: akreditifte bankalar, şartlara uyan belgelere karşı ödeme yapar. Malı ya da fabrikayı denetlemezler.","fa":"The documents درست است: در اعتبار اسنادی بانک‌ها در برابر مدارکی پول می‌دهند که با شرایط جور باشند. کالا یا کارخانه را بازرسی نمی‌کنند."}},{"from":"sales-3-2","kind":"blank","prompt":"If we ___ your label to the carton, would you order more?","options":["add","added","will add"],"correct":1,"point":2,"why":{"en":"added: 'would you' shows a possible deal, so 'if' takes the past. 'Add' goes with 'will you', and 'will add' never follows if here.","tr":"added: 'would you' olası bir anlaşmayı gösterir, bu yüzden 'if' geçmiş zaman alır. 'Add' 'will you' ile gelir; 'will add' burada if'ten sonra gelmez.","fa":"added درست است، چون would you یک معامله‌ی احتمالی است و بعد از if گذشته می‌آید. add با will you می‌آید و will add اینجا بعد از if نمی‌آید."}},{"from":"sales-3-1","kind":"mcq","prompt":"Which line follows \"Agree, then answer\"?","options":["You're wrong about the price, and I can prove it.","I can give you 15% off if you order today.","I understand. However, the price includes freight."],"correct":2,"point":1,"why":{"en":"'I understand. However...' agrees first, then gives one fact. Telling the buyer they're wrong, or jumping to 15% off, breaks the method.","tr":"'I understand. However...' önce kabul eder, sonra bir bilgi verir. Alıcıya yanıldığını söylemek ya da hemen %15 indirim yöntemi bozar.","fa":"«I understand. However...» اول می‌پذیرد و بعد یک واقعیت می‌گوید. گفتن اینکه خریدار اشتباه می‌کند یا پریدن به ۱۵ درصد تخفیف روش را خراب می‌کند."}},{"from":"sales-1-2","kind":"mcq","prompt":"Which is the best small request in a first email?","options":["Could I send you two samples?","Please order now.","Please read our 40-page catalogue."],"correct":0,"point":1,"why":{"en":"'Could I send you two samples?' is easy to say yes to. 'Order now' and a 40-page catalogue ask too much of a stranger.","tr":"'Could I send you two samples?' sorusuna evet demek kolaydır. 'Order now' ve 40 sayfalık katalog tanımadığın birinden fazla şey ister.","fa":"به «Could I send you two samples?» راحت می‌شود بله گفت. «order now» و کاتالوگ ۴۰ صفحه‌ای از کسی که تو را نمی‌شناسد زیادی می‌خواهند."}}]},"explain":{"id":"c-sales-3-3-e","course":"sales","unit":"sales-3-3","type":"explain","level":"B1","title":{"en":"Order confirmation and shipping documents","tr":"Sipariş onayı ve sevkiyat belgeleri","fa":"تأییدیه‌ی سفارش و مدارک حمل"},"objective":{"en":"After this lesson, you can confirm an order in writing, check it against the quote, and name the main shipping documents.","tr":"Bu dersin sonunda bir siparişi yazılı olarak onaylayabilecek, teklifle karşılaştırabilecek ve temel sevkiyat belgelerini tanıyabileceksin.","fa":"بعد از این درس می‌توانی سفارش را کتبی تأیید کنی، آن را با پیشنهاد قیمت مقایسه کنی و مدارک اصلی حمل را بشناسی."},"hook":{"en":"Confirm every order in writing and check it against your quote before you ship. One wrong word on a document can stop a container at the port or delay your payment.","tr":"Her siparişi yazılı onayla ve sevkiyattan önce teklifinle karşılaştır. Bir belgedeki tek yanlış kelime konteyneri limanda durdurabilir ya da ödemeni geciktirebilir.","fa":"هر سفارش را کتبی تأیید کن و قبل از ارسال با پیشنهادت مقایسه کن. یک کلمه‌ی اشتباه روی یک مدرک می‌تواند کانتینر را در بندر نگه دارد یا پرداختت را عقب بیندازد."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"From order to shipment","tr":"Siparişten sevkiyata","fa":"از سفارش تا ارسال"},"steps":[{"en":"Compare the buyer's purchase order with your quote, line by line. Terms sometimes change by mistake.","tr":"Alıcının satın alma siparişini teklifinle satır satır karşılaştır. Koşullar bazen yanlışlıkla değişir.","fa":"سفارش خرید مشتری را خط به خط با پیشنهادت مقایسه کن، چون شرایط گاهی به‌اشتباه عوض می‌شوند.","ex":"Quote: FCA Izmir. PO: CIF Hamburg. Ask now."},{"en":"Raise any difference at once, in writing. After shipment it becomes a dispute.","tr":"Her farkı hemen ve yazılı bildir. Sevkiyattan sonra bu bir anlaşmazlığa dönüşür.","fa":"هر اختلافی را فوری و کتبی مطرح کن، چون بعد از ارسال به دعوای تجاری تبدیل می‌شود.","ex":"Your PO says CIF. Our quote was FCA. Which is right?"},{"en":"Confirm every term: product, quantity, price, Incoterm, payment, dates. Then both sides hold the same deal.","tr":"Her koşulu onayla: ürün, miktar, fiyat, Incoterm, ödeme, tarihler. Böylece iki tarafın elinde de aynı anlaşma olur.","fa":"همه‌ی شرایط را تأیید کن: محصول، مقدار، قیمت، اینکوترم، پرداخت، تاریخ. این‌طوری هر دو طرف یک توافق را در دست دارند.","ex":"200 cartons, EUR 40.00 each, FCA Izmir, Incoterms 2020."},{"en":"Names, weights and descriptions must match on every document, because customs and banks compare them.","tr":"Adlar, ağırlıklar ve tanımlar her belgede uyuşmalı; çünkü gümrük ve bankalar bunları karşılaştırır.","fa":"نام‌ها، وزن‌ها و شرح کالا باید در همه‌ی مدارک همخوانی داشته باشند، چون گمرک و بانک‌ها آن‌ها را با هم مقایسه می‌کنند.","ex":"Invoice: 1,000 kg. Packing list: 1,000 kg."}],"table":{"headers":{"en":["Document","What it does"],"tr":["Belge","Ne işe yarar"],"fa":["مدرک","چه کاری می‌کند"]},"rows":[["Proforma invoice","a draft invoice before shipping, not yet a bill"],["Commercial invoice","the seller's bill to the buyer"],["Packing list","what is in each box, with weights"],["Bill of lading","carrier's receipt; the original usually lets you collect the goods"],["Certificate of origin","where the goods were made"]]}},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Order confirmations: is packed, will be shipped","tr":"Sipariş onayları: is packed, will be shipped","fa":"تأیید سفارش: is packed و will be shipped"},"steps":[{"en":"The goods matter, not who packs them: use be + past participle.","tr":"Önemli olan mal, onu kimin paketlediği değil: be + fiilin üçüncü hâli kullan.","fa":"چیزی که مهم است کالاست، نه کسی که بسته‌بندی‌اش می‌کند؛ پس be و اسم مفعول بیاور.","ex":"All cartons are packed on pallets."},{"en":"For a future step, use will be + past participle.","tr":"Gelecekteki bir adım için will be + fiilin üçüncü hâli kullan.","fa":"برای مرحله‌ای در آینده will be و اسم مفعول بیاور.","ex":"The first delivery will be shipped on 1 May."},{"en":"For a step just done, use has / have been + past participle.","tr":"Az önce tamamlanan bir adım için has / have been + fiilin üçüncü hâli kullan.","fa":"برای مرحله‌ای که همین حالا انجام شده has been یا have been و اسم مفعول بیاور.","ex":"Your order has been confirmed."},{"en":"Use a real date or clear event, so the buyer can plan.","tr":"Gerçek bir tarih ya da açık bir olay kullan ki alıcı plan yapabilsin.","fa":"تاریخ واقعی یا یک رویداد روشن بگو تا خریدار بتواند برنامه‌ریزی کند.","ex":"six weeks after the deposit arrives"}],"table":{"headers":{"en":["Time","Passive","Example"],"tr":["Zaman","Edilgen","Örnek"],"fa":["زمان","مجهول","مثال"]},"rows":[["always / usually","am / is / are + past participle","All cartons are packed on pallets."],["future","will be + past participle","The first delivery will be shipped on 1 May."],["done now","has / have been + past participle","Your order has been confirmed."]]},"tip":{"en":"Turkish makes the passive with a verb ending ('paketlenir', 'gönderilecek'), with no separate 'be', so learners write 'will shipped'. Persian adds «شدن» («ارسال خواهد شد»), which works like English be.","tr":"Türkçede edilgen yapı fiil ekiyle kurulur ('paketlenir', 'gönderilecek'); ayrı bir 'be' yoktur. Bu yüzden İngilizcede 'will shipped' yazılıyor. İngilizcede be şarttır: will be shipped.","fa":"در فارسی مجهول را با «شدن» می‌سازیم: «ارسال خواهد شد»، «بسته‌بندی می‌شوند». فعل be در انگلیسی همان نقش «شدن» را دارد؛ پس نباید جا بیفتد: will be shipped."},"wrong":"Your order will be ship on Monday.","right":"Your order will be shipped on Monday."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Letters of credit are strict","tr":"Akreditif katı kurallıdır","fa":"اعتبار اسنادی سخت‌گیر است"},"body":{"en":"With an L/C, banks check documents, not goods. A small mismatch can delay payment. Read it the day it arrives and ask for changes before shipping. Ask your forwarder which documents your buyer's country needs.","tr":"Akreditifte bankalar malı değil, belgeleri kontrol eder. Küçük bir uyumsuzluk ödemeyi geciktirebilir. Akreditifi geldiği gün oku ve sevkiyattan önce değişiklik iste. Alıcının ülkesinin hangi belgeleri istediğini nakliyecine sor.","fa":"در اعتبار اسنادی، بانک‌ها مدارک را بررسی می‌کنند، نه کالا را. یک مغایرت کوچک می‌تواند پرداخت را عقب بیندازد. ال‌سی را همان روزی که می‌رسد بخوان و قبل از ارسال اصلاحش را بخواه. از فورواردرت بپرس کشور خریدار چه مدارکی لازم دارد."},"phrases":[{"phrase":"Let me read that back to you.","meaning":{"en":"Checks the order aloud.","tr":"Siparişi sesli kontrol eder.","fa":"سفارش را با صدای بلند بررسی می‌کند."}},{"phrase":"I noticed a difference between ... and ...","meaning":{"en":"Raises a mismatch politely.","tr":"Bir uyumsuzluğu kibarca belirtir.","fa":"مؤدبانه یک مغایرت را مطرح می‌کند."}},{"phrase":"... will be sent by ...","meaning":{"en":"Says when the documents go.","tr":"Belgelerin ne zaman gideceğini söyler.","fa":"می‌گوید مدارک کی فرستاده می‌شوند."}},{"phrase":"purchase order","meaning":{"en":"The buyer's official document that orders goods.","tr":"satın alma siparişi.","fa":"سفارش خرید"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A confirmation with no doubts","tr":"Şüphe bırakmayan bir onay","fa":"تأییدیه‌ای بدون ابهام"},"item":"Thanks for your order! We will send everything soon. Your facts: order 4471; 200 cartons at EUR 40.00; FCA Izmir; ships four weeks after the deposit.","answer":"Your order 4471 has been confirmed: 200 cartons at EUR 40.00, FCA Izmir, Incoterms 2020. The goods will be shipped four weeks after the deposit arrives.","walk":[{"en":"Use the order number, so nobody can mix up two orders.","tr":"Sipariş numarasını kullan ki kimse iki siparişi karıştırmasın.","fa":"شماره‌ی سفارش را بیاور تا کسی دو سفارش را با هم اشتباه نگیرد."},{"en":"Repeat every term, even if it seems obvious.","tr":"Açık görünse bile her koşulu tekrar et.","fa":"همه‌ی شرایط را تکرار کن، حتی اگر به نظرت بدیهی است."},{"en":"Replace 'soon' with a date, or a clear event.","tr":"'Soon' yerine bir tarih ya da net bir olay yaz.","fa":"به‌جای کلمه‌ی soon تاریخ یا یک رویداد مشخص بنویس."}]},"quick":{"prompt":"The buyer's PO says CIF, but your quote said FCA. You should ___.","options":["raise it in writing now","ship and say nothing","change your price quietly"],"correct":0,"why":{"en":"raise it in writing now: a small difference today is a big dispute after shipment.","tr":"raise it in writing now: bugünkü küçük fark, sevkiyattan sonra büyük bir anlaşmazlık olur.","fa":"بهترین کار raise it in writing now است، چون اختلاف کوچک امروز بعد از ارسال به دعوای بزرگ تبدیل می‌شود."}},"remember":{"en":"If it isn't in writing, it isn't agreed. You can now confirm an order with every term and name the five main shipping documents.","tr":"Yazılı değilse, anlaşılmış değildir. Artık bir siparişi tüm koşullarıyla onaylayabilir ve beş temel belgeyi tanıyabilirsin.","fa":"اگر کتبی نیست، توافق نشده است. حالا می‌توانی سفارش را با همه‌ی شرایطش تأیید کنی و پنج مدرک اصلی را بشناسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Rules in a contract: must be paid, can't be shipped","tr":"Sözleşmedeki kurallar: must be paid, can't be shipped","fa":"قاعده‌های قرارداد: must be paid و can't be shipped"},"steps":[{"en":"Modal + be + past participle: a rule with no person.","tr":"Modal + be + fiilin üçüncü hâli: kişisiz bir kural.","fa":"با فعل وجهی، be و اسم مفعول قاعده‌ای می‌گویی که نام کسی در آن نیست.","ex":"The deposit must be paid first."},{"en":"must = required; can't = not allowed; should = expected.","tr":"must = zorunlu; can't = izin yok; should = beklenen.","fa":"کلمه‌ی must یعنی الزامی، can't یعنی مجاز نیست و should یعنی انتظار می‌رود.","ex":"The goods can't be shipped without the certificate."},{"en":"Keep all three parts; never drop be or -ed.","tr":"Üç parçayı da koru; be'yi ya da -ed'i asla atlama.","fa":"هر سه بخش را نگه دار و be یا اسم مفعول را جا نینداز.","ex":"It should be signed by both sides."}],"table":{"headers":{"en":["Modal","be + past participle","Example"],"tr":["Modal","be + fiilin üçüncü hâli","Örnek"],"fa":["فعل وجهی","be و اسم مفعول","مثال"]},"rows":[["must","be paid","The deposit must be paid first."],["can't","be shipped","The goods can't be shipped without the certificate."],["should","be signed","It should be signed by both sides."]]},"body":{"en":"B2: write one rule in your confirmation with must be, can't be or should be + past participle.","tr":"B2: onayına must be, can't be ya da should be + fiilin üçüncü hâli ile bir kural yaz.","fa":"مسیر B2: در تأییدیه‌ات یک قاعده با must be، can't be یا should be و اسم مفعول بنویس."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
